from scipy.io import mmread
root=Path(__file__).resolve().parents[3];work=Path(__file__).resolve().parent
read=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
r=read(work/'results.json');e=read(work/'exact-closure-results.json');cases=r['cases']+e['cases'];table=[]
for c in cases:
 m=c['spectral']['rightmost_found'][0];table.append({'name':c['name'],'leading_real':m['real'],'leading_imag':m['imag'],'eigen_residual':m['absolute_residual_l2'],'squared_mode_fraction_r_gt_.8':m['squared_fraction_r_gt_.8'],'constant_residual':c['export']['constant_residual_linf'],'actual_native_fill_stencil_matvec_error':c['export']['native_fill_stencil_matvec_max_error'],'peak_pulse_amplitude':c['pulse']['peak_sampled_linf'],'peak_pulse_error':c['pulse']['peak_error_linf'],'pulse_last_recorded_time':c['pulse']['last']['time'],'pulse_stop':c['pulse']['stop']})
changes=[]
for n,span in [(16,2.2),(20,2.2),(24,2.2),(24,2.1)]:
 name=f'N{n}-span{span}-ray-centered-ko0.1';A=mmread(str(work/name)+'.mtx').tocsr();points=np.genfromtxt(str(work/name)+'-points.csv',delimiter=',',names=True);xyz=np.column_stack([points[d] for d in ['x','y','z']]);h=span/n;interior=np.ones(len(points),dtype=bool)
 for d in range(3):
  for off in [-2,-1,1,2]:
   shifted=xyz.copy();shifted[:,d]+=off*h;interior&=(shifted*shifted).sum(axis=1)<1
 for closure in ['nearest','fallback']:
  B=mmread(str(work/f'N{n}-span{span}-{closure}-centered-ko0.1')+'.mtx').tocsr();D=A-B;bad=(abs(D).sum(axis=1).A.ravel()>1e-13);maximum=float(abs(D[interior]).max()) if interior.any() else 0.;assert maximum<1e-13
  changes.append({'n':n,'span':span,'alternative':closure,'unchanged_rows_whose_all_centered_advection_samples_are_inside':int(interior.sum()),'changed_rows':int(bad.sum()),'changed_rows_with_all_advection_samples_inside':int((bad&interior).sum()),'maximum_change_on_strict_interior_advection_rows':maximum})
rejections=[]
for n in [12,16]:
 cmd=[str(work/'export-operator'),str(n),'2.1','ray','upwind','.1',str(work/f'rejected-span2.1-N{n}')];done=subprocess.run(cmd,capture_output=True,text=True);rejections.append({'command':cmd,'exit_status':done.returncode,'stderr':done.stderr});assert done.returncode!=0
# Freeze exact compiler, dependencies, library bytes and all executed source variants.
cmd=read(work/'build-command.json');source=work/'export_operator.cpp';exe=work/'export-operator';source_index=cmd.index(str(source));common=cmd[:source_index];dep_command=common+['-M',str(source)];done=subprocess.run(dep_command,capture_output=True,text=True);done.check_returncode();(work/'dependencies.d').write_text(done.stdout)
